CREATE TABLE public.departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE CHECK (length(trim(name)) BETWEEN 1 AND 50), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.departments TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.departments TO authenticated;
GRANT ALL ON public.departments TO service_role;
ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.department_memberships (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, department_id uuid NOT NULL REFERENCES public.departments(id), role text NOT NULL CHECK (role IN ('manager','teacher')));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.department_memberships TO authenticated;
GRANT ALL ON public.department_memberships TO service_role;
ALTER TABLE public.department_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.classes ADD COLUMN department_id uuid REFERENCES public.departments(id);
CREATE INDEX classes_department_idx ON public.classes(department_id);
CREATE OR REPLACE FUNCTION public.manages_department(_user uuid, _department uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.department_memberships WHERE user_id=_user AND department_id=_department AND role='manager') $$;
CREATE OR REPLACE FUNCTION public.can_access_department(_user uuid, _department uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user,'admin') OR EXISTS (SELECT 1 FROM public.department_memberships WHERE user_id=_user AND department_id=_department) $$;
CREATE OR REPLACE FUNCTION public.can_access_class(_user uuid, _class uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user,'admin') OR EXISTS (SELECT 1 FROM public.classes c WHERE c.id=_class AND public.can_access_department(_user,c.department_id)) $$;
CREATE OR REPLACE FUNCTION public.can_record_attendance(_user uuid, _class uuid, _date date) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _date<=CURRENT_DATE AND (public.has_role(_user,'admin') OR EXISTS (SELECT 1 FROM public.classes c JOIN public.department_memberships m ON m.department_id=c.department_id WHERE c.id=_class AND m.user_id=_user AND (m.role='manager' OR _date=CURRENT_DATE))) $$;
CREATE OR REPLACE FUNCTION public.can_read_staff_profile(_user uuid, _target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user=_target OR public.has_role(_user,'admin') OR EXISTS (SELECT 1 FROM public.department_memberships m WHERE m.user_id=_target AND public.manages_department(_user,m.department_id)) $$;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR EXISTS (SELECT 1 FROM public.department_memberships WHERE user_id=_user_id) $$;
REVOKE ALL ON FUNCTION public.manages_department(uuid,uuid), public.can_access_department(uuid,uuid), public.can_access_class(uuid,uuid), public.can_record_attendance(uuid,uuid,date), public.can_read_staff_profile(uuid,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.manages_department(uuid,uuid), public.can_access_department(uuid,uuid), public.can_access_class(uuid,uuid), public.can_record_attendance(uuid,uuid,date), public.can_read_staff_profile(uuid,uuid) TO authenticated, service_role;
CREATE POLICY "department read" ON public.departments FOR SELECT TO authenticated USING (public.can_access_department(auth.uid(),id));
CREATE POLICY "admin department write" ON public.departments FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "membership read" ON public.department_memberships FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.manages_department(auth.uid(),department_id));
CREATE POLICY "admin membership write" ON public.department_memberships FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
DROP POLICY "staff read classes" ON public.classes;
CREATE POLICY "scoped classes read" ON public.classes FOR SELECT TO authenticated USING (public.can_access_department(auth.uid(),department_id));
DROP POLICY "staff read students" ON public.students;
CREATE POLICY "scoped students read" ON public.students FOR SELECT TO authenticated USING (public.can_access_class(auth.uid(),class_id));
DROP POLICY "staff read grades" ON public.grades;
CREATE POLICY "scoped grades read" ON public.grades FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.classes c WHERE c.grade_id=grades.id));
DROP POLICY "staff read attendance" ON public.attendance;
DROP POLICY "staff insert attendance" ON public.attendance;
DROP POLICY "staff update attendance" ON public.attendance;
CREATE POLICY "scoped attendance read" ON public.attendance FOR SELECT TO authenticated USING (public.can_access_class(auth.uid(),class_id));
CREATE POLICY "scoped attendance insert" ON public.attendance FOR INSERT TO authenticated WITH CHECK (public.can_record_attendance(auth.uid(),class_id,date));
CREATE POLICY "scoped attendance update" ON public.attendance FOR UPDATE TO authenticated USING (public.can_record_attendance(auth.uid(),class_id,date)) WITH CHECK (public.can_record_attendance(auth.uid(),class_id,date));
DROP POLICY "own profile or admin read" ON public.profiles;
CREATE POLICY "scoped profiles read" ON public.profiles FOR SELECT TO authenticated USING (public.can_read_staff_profile(auth.uid(),id));
CREATE FUNCTION public.validate_attendance_class() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.students WHERE id=NEW.student_id AND class_id=NEW.class_id) THEN RAISE EXCEPTION 'Student must belong to the selected class'; END IF; RETURN NEW; END $$;
CREATE TRIGGER attendance_class_validation BEFORE INSERT OR UPDATE ON public.attendance FOR EACH ROW EXECUTE FUNCTION public.validate_attendance_class();
CREATE FUNCTION public.set_department_access(_target uuid, _department uuid, _role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
IF _role NOT IN ('manager','teacher','none') THEN RAISE EXCEPTION 'Invalid department role'; END IF;
IF NOT public.has_role(auth.uid(),'admin') THEN
 IF NOT public.manages_department(auth.uid(),_department) OR _target=auth.uid() OR _role='manager' OR public.has_role(_target,'admin') OR EXISTS (SELECT 1 FROM public.department_memberships WHERE user_id=_target AND (department_id<>_department OR role='manager')) THEN RAISE EXCEPTION 'Only school administrators can assign managers or move staff'; END IF;
END IF;
IF _role='none' THEN DELETE FROM public.department_memberships WHERE user_id=_target AND department_id=_department;
ELSE INSERT INTO public.department_memberships(user_id,department_id,role) VALUES (_target,_department,_role) ON CONFLICT(user_id) DO UPDATE SET department_id=EXCLUDED.department_id,role=EXCLUDED.role; END IF;
END $$;
CREATE FUNCTION public.add_department_teacher(_email text, _department uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN
IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.manages_department(auth.uid(),_department)) THEN RAISE EXCEPTION 'Department manager access required'; END IF;
SELECT id INTO target FROM public.profiles WHERE lower(email)=lower(trim(_email));
IF target IS NULL THEN RAISE EXCEPTION 'An existing registered staff account is required'; END IF;
PERFORM public.set_department_access(target,_department,'teacher'); END $$;
CREATE FUNCTION public.set_school_role(_target uuid, _role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') OR _target=auth.uid() THEN RAISE EXCEPTION 'Administrator access required; your own role cannot be changed'; END IF;
IF _role NOT IN ('admin','teacher','none') THEN RAISE EXCEPTION 'Invalid role'; END IF;
DELETE FROM public.user_roles WHERE user_id=_target;
IF _role<>'none' THEN INSERT INTO public.user_roles(user_id,role) VALUES (_target,_role::public.app_role); ELSE DELETE FROM public.department_memberships WHERE user_id=_target; END IF;
END $$;
REVOKE ALL ON FUNCTION public.set_department_access(uuid,uuid,text),public.add_department_teacher(text,uuid),public.set_school_role(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_department_access(uuid,uuid,text),public.add_department_teacher(text,uuid),public.set_school_role(uuid,text) TO authenticated;
